"use client"

import * as React from "react"

import type { BlobViewerSource, UrlViewerSource } from "@/lib/viewer-source"
import { cn } from "@/lib/utils"
import {
  createViewerResource,
  type ViewerResource,
} from "@/lib/viewer-resource"

import {
  getPptxFitScale,
  getPptxResetKey,
  type PptxSlideOverlayProps,
} from "./pptx-viewer-core"
import { PptxErrorBoundary } from "./pptx-viewer-error-boundary"
import { PptxViewerFallback } from "./pptx-viewer-fallback"
import { useRetainedPptxSource } from "./pptx-viewer-hooks"
import { createPptxScrollActivity } from "./pptx-viewer-scroll"
import { PptxSlideScroller } from "./pptx-viewer-slide"
import { PptxToolbar } from "./pptx-viewer-toolbar"
import { usePptxViewportWidth } from "./pptx-viewer-viewport"
import { usePptxVisibleSlide } from "./pptx-viewer-visible-slide"
import { usePptxZoom } from "./pptx-viewer-zoom"

export type { PptxSlideOverlayProps }
export type PptxDocumentSource = UrlViewerSource | BlobViewerSource

/** Client gate without an effect: false during SSR, true after hydration. */
function useIsClient() {
  return React.useSyncExternalStore(
    () => () => {},
    () => true,
    () => false
  )
}

export interface PptxViewerProps {
  /** Canonical presentation source. Prefer this for new integrations. */
  source?: PptxDocumentSource
  /** URL of the .pptx (same-origin or CORS-enabled). Kept for compatibility. */
  src?: string
  className?: string
  /** Controlled scale. When omitted, the viewer owns zoom state. */
  scale?: number
  /** Initial uncontrolled scale. When omitted, uncontrolled mode starts fit-width. */
  defaultScale?: number
  /** Called by zoom controls. `null` means return to fit-width mode. */
  onScaleChange?: (scale: number | null) => void
  toolbar?: boolean
  downloadFileName?: string
  /** Render absolutely-positioned overlays, such as bbox citations, on each slide. */
  renderSlideOverlay?: (props: PptxSlideOverlayProps) => React.ReactNode
  /** Fired with the 1-based slide nearest the top of the viewport as you scroll. */
  onVisibleSlideChange?: (slide: number) => void
  /** Fired with scroll progress in [0, 1]. */
  onScrollProgressChange?: (progress: number) => void
  /** Drop the outer border/rounded/background so the viewer fills its container. */
  bare?: boolean
  /** Rendered as a full-width strip directly below the toolbar. */
  header?: React.ReactNode
  /** Rendered as a left rail alongside the scrolling slides. */
  aside?: React.ReactNode
  /**
   * Render slides as soon as they near the viewport, even mid-scroll. Defaults to
   * false: uncached renders wait until scrolling settles.
   */
  eager?: boolean
}

export function PptxViewer(props: PptxViewerProps) {
  const isClient = useIsClient()
  const { downloadFileName, source, src } = props
  const resource = React.useMemo(() => createPptxViewerResource({
    downloadFileName,
    source,
    src,
  }), [
    downloadFileName,
    source,
    src,
  ])
  if (!isClient) {
    return <PptxViewerFallback className={props.className} bare={props.bare} />
  }
  return (
    <PptxErrorBoundary
      className={props.className}
      bare={props.bare}
      download={resource.getDownload()}
      resetKey={getPptxResetKey({
        identityKey: resource.identityKey,
        scale: props.scale,
        defaultScale: props.defaultScale,
        eager: props.eager,
      })}
    >
      <React.Suspense
        fallback={
          <PptxViewerFallback className={props.className} bare={props.bare} />
        }
      >
        <PptxViewerContent {...props} resource={resource} />
      </React.Suspense>
    </PptxErrorBoundary>
  )
}

function PptxViewerContent({
  resource,
  className,
  scale: controlledScale,
  defaultScale,
  onScaleChange,
  toolbar = true,
  renderSlideOverlay,
  onVisibleSlideChange,
  onScrollProgressChange,
  bare = false,
  header,
  aside,
  eager = false,
}: PptxViewerProps & { resource: ViewerResource }) {
  const source = useRetainedPptxSource(resource)
  const download = React.useMemo(() => resource.getDownload(), [resource])

  const [rotation, setRotation] = React.useState(0)
  const scrollActivity = React.useMemo(() => createPptxScrollActivity(), [])
  const { containerRef, viewportWidth } = usePptxViewportWidth()
  const { currentSlide, handleScroll, scrollViewportRef } = usePptxVisibleSlide(
    {
      onScrollProgressChange,
      onVisibleSlideChange,
    }
  )

  const fitScale = getPptxFitScale(viewportWidth, source.baseSize.width)
  const { scaleControlsDisabled, setViewerScale, zoomScale } = usePptxZoom({
    controlledScale,
    defaultScale,
    fitScale,
    onScaleChange,
  })

  const handleViewportScroll = React.useCallback(() => {
    if (!eager) scrollActivity.handleScroll()
    handleScroll()
  }, [eager, handleScroll, scrollActivity])

  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="pptx-viewer"
    >
      {toolbar ? (
        <PptxToolbar
          currentSlide={currentSlide}
          slideCount={source.slideCount}
          zoomScale={zoomScale}
          scaleControlsDisabled={scaleControlsDisabled}
          download={download}
          onZoom={(factor) => setViewerScale(zoomScale * factor)}
          onFitWidth={() => setViewerScale(null)}
          onRotate={() => setRotation((value) => (value + 90) % 360)}
        />
      ) : null}

      <div className="flex min-h-0 flex-1">
        {aside ? (
          <div data-slot="pptx-viewer-aside" className="flex-shrink-0">
            {aside}
          </div>
        ) : null}
        <div className="flex min-h-0 min-w-0 flex-1 flex-col">
          {header ? <div data-slot="pptx-viewer-header">{header}</div> : null}
          <PptxSlideScroller
            source={source}
            zoomScale={zoomScale}
            rotation={rotation}
            eager={eager}
            activity={scrollActivity}
            renderSlideOverlay={renderSlideOverlay}
            containerRef={containerRef}
            viewportRef={scrollViewportRef}
            onScroll={handleViewportScroll}
          />
        </div>
      </div>
    </div>
  )
}

function createPptxViewerResource({
  source,
  src,
  downloadFileName,
}: Pick<PptxViewerProps, "source" | "src" | "downloadFileName">) {
  if (source) {
    return createViewerResource(source, { fileName: downloadFileName })
  }
  if (src) {
    return createViewerResource(
      {
        kind: "url",
        url: src,
        fileName: downloadFileName,
      },
      { fileName: downloadFileName }
    )
  }
  throw new Error("PptxViewer requires either source or src.")
}

import {
  resolveViewerDescriptor,
  type BlobViewerSource,
  type TextSource,
  type UrlViewerSource,
  type ViewerDescriptor,
  type ViewerSource,
} from "@/lib/viewer-source"

export interface ResourceReadOptions {
  signal?: AbortSignal
}

export interface TextReadOptions extends ResourceReadOptions {
  maxBytes?: number
  maxLines?: number
}

export interface ByteRange {
  start: number
  end: number
}

export interface ByteRangeResult {
  buffer: ArrayBuffer
  contentRange?: {
    start: number
    end: number
    total: number | null
  }
  isComplete: boolean
}

export type DownloadCapability =
  | { kind: "href"; href: string; fileName: string }
  | { kind: "blob"; blob: Blob; fileName: string }
  | { kind: "text"; text: string; fileName: string; mimeType?: string }
  | { kind: "none"; fileName: string }

export interface ViewerResource {
  readonly source: ViewerSource
  readonly descriptor: ViewerDescriptor
  readonly identityKey: string
  readonly fileName: string
  readonly mimeType?: string

  getDownload(): DownloadCapability
  readBlob(options?: ResourceReadOptions): Promise<Blob>
  readArrayBuffer(options?: ResourceReadOptions): Promise<ArrayBuffer>
  readText(options?: TextReadOptions): Promise<string>
  stream(options?: ResourceReadOptions): Promise<ReadableStream<Uint8Array>>
  readRange(
    range: ByteRange,
    options?: ResourceReadOptions
  ): Promise<ByteRangeResult>
}

export type ResourceErrorKind =
  | "fetch_failed"
  | "http_error"
  | "aborted"
  | "too_large"
  | "unsupported_capability"
  | "unknown"

export type ResourceTooLargeReason = "bytes" | "lines"

export class ResourceError extends Error {
  readonly kind: ResourceErrorKind
  readonly status?: number
  readonly tooLargeReason?: ResourceTooLargeReason
  override readonly cause?: unknown

  constructor({
    kind,
    message,
    status,
    tooLargeReason,
    cause,
  }: {
    kind: ResourceErrorKind
    message: string
    status?: number
    tooLargeReason?: ResourceTooLargeReason
    cause?: unknown
  }) {
    super(message)
    this.name = "ResourceError"
    this.kind = kind
    this.status = status
    this.tooLargeReason = tooLargeReason
    this.cause = cause
  }
}

export interface DescriptorOptions {
  fileName?: string
  mimeType?: string
}

export function createViewerResource(
  source: ViewerSource,
  options: DescriptorOptions = {}
): ViewerResource {
  const descriptor = resolveViewerDescriptor({ source, ...options })
  switch (source.kind) {
    case "url":
      return createUrlResource(source, descriptor)
    case "blob":
      return createBlobResource(source, descriptor)
    case "text":
      return createTextResource(source, descriptor)
  }
}

export function blobSource(
  bytes: Blob | ArrayBuffer | Uint8Array,
  metadata: {
    identityKey: string
    fileName?: string
    mimeType?: string
    downloadUrl?: string
  }
): BlobViewerSource {
  const blob =
    bytes instanceof Blob
      ? bytes
      : new Blob([bytes instanceof ArrayBuffer ? bytes : new Uint8Array(bytes)], {
          type: metadata.mimeType ?? "",
        })
  return {
    kind: "blob",
    blob,
    fileName: metadata.fileName,
    mimeType: metadata.mimeType ?? blob.type,
    downloadUrl: metadata.downloadUrl,
    identityKey: metadata.identityKey,
  }
}

function createUrlResource(
  source: UrlViewerSource,
  descriptor: ViewerDescriptor
): ViewerResource {
  return resourceBase(source, descriptor, {
    getDownload: () => ({
      kind: "href",
      href: source.downloadUrl ?? source.url,
      fileName: descriptor.downloadFileName,
    }),
    readBlob: async ({ signal } = {}) => {
      const response = await fetchResource(source.url, { signal })
      return response.blob()
    },
    readArrayBuffer: async ({ signal } = {}) => {
      const response = await fetchResource(source.url, { signal })
      return response.arrayBuffer()
    },
    readText: async ({ signal, maxBytes, maxLines } = {}) => {
      const response = await fetchResource(source.url, { signal })
      return readBoundedResponseText(response, { maxBytes, maxLines })
    },
    stream: async ({ signal } = {}) => {
      const response = await fetchResource(source.url, { signal })
      if (!response.body) {
        throw new ResourceError({
          kind: "unsupported_capability",
          message: "This response cannot be streamed.",
        })
      }
      return response.body
    },
    readRange: async ({ start, end }, { signal } = {}) => {
      const response = await fetchResource(source.url, {
        signal,
        headers: { Range: `bytes=${start}-${end}` },
      })
      const buffer = await response.arrayBuffer()
      return {
        buffer,
        contentRange: parseContentRange(response.headers.get("content-range")),
        isComplete: response.status === 200 || buffer.byteLength <= end - start,
      }
    },
  })
}

function createBlobResource(
  source: BlobViewerSource,
  descriptor: ViewerDescriptor
): ViewerResource {
  const blob = source.blob
  return resourceBase(source, descriptor, {
    getDownload: () =>
      source.downloadUrl
        ? {
            kind: "href",
            href: source.downloadUrl,
            fileName: descriptor.downloadFileName,
          }
        : {
            kind: "blob",
            blob,
            fileName: descriptor.downloadFileName,
          },
    readBlob: async () => blob,
    readArrayBuffer: async () => blob.arrayBuffer(),
    readText: async ({ maxBytes, maxLines } = {}) =>
      readBoundedBlobText(blob, { maxBytes, maxLines }),
    stream: async () => blob.stream(),
    readRange: async ({ start, end }) => {
      const rangeBlob = blob.slice(start, end + 1)
      return {
        buffer: await rangeBlob.arrayBuffer(),
        contentRange: {
          start,
          end: Math.min(end, Math.max(0, blob.size - 1)),
          total: blob.size,
        },
        isComplete: end >= blob.size - 1,
      }
    },
  })
}

function createTextResource(
  source: TextSource,
  descriptor: ViewerDescriptor
): ViewerResource {
  return resourceBase(source, descriptor, {
    getDownload: () => ({
      kind: "text",
      text: source.text,
      fileName: descriptor.downloadFileName,
      mimeType: descriptor.mimeType,
    }),
    readBlob: async () =>
      new Blob([source.text], {
        type: descriptor.mimeType ?? "text/plain;charset=utf-8",
      }),
    readArrayBuffer: async () => new TextEncoder().encode(source.text).buffer,
    readText: async ({ maxBytes, maxLines } = {}) =>
      readBoundedInlineText(source.text, { maxBytes, maxLines }),
    stream: async () => new Blob([source.text]).stream(),
    readRange: async ({ start, end }) => {
      const buffer = new TextEncoder().encode(source.text)
      const slice = buffer.slice(start, end + 1)
      return {
        buffer: slice.buffer,
        contentRange: {
          start,
          end: Math.min(end, Math.max(0, buffer.byteLength - 1)),
          total: buffer.byteLength,
        },
        isComplete: end >= buffer.byteLength - 1,
      }
    },
  })
}

function resourceBase(
  source: ViewerSource,
  descriptor: ViewerDescriptor,
  methods: Pick<
    ViewerResource,
    | "getDownload"
    | "readBlob"
    | "readArrayBuffer"
    | "readText"
    | "stream"
    | "readRange"
  >
): ViewerResource {
  return {
    source,
    descriptor,
    identityKey: descriptor.identityKey,
    fileName: descriptor.downloadFileName,
    mimeType: descriptor.mimeType,
    ...methods,
  }
}

async function fetchResource(
  input: RequestInfo | URL,
  init?: RequestInit
): Promise<Response> {
  let response: Response
  try {
    response = await fetch(input, init)
  } catch (error) {
    if (isAbortError(error)) {
      throw new ResourceError({
        kind: "aborted",
        message: "Loading was cancelled.",
        cause: error,
      })
    }
    throw new ResourceError({
      kind: "fetch_failed",
      message: "Could not fetch this resource.",
      cause: error,
    })
  }

  if (!response.ok && response.status !== 206) {
    throw new ResourceError({
      kind: "http_error",
      message: `Failed to load resource: ${response.status}`,
      status: response.status,
    })
  }

  return response
}

async function readBoundedResponseText(
  response: Response,
  bounds: { maxBytes?: number; maxLines?: number }
) {
  const maxBytes = bounds.maxBytes
  const contentLength = response.headers.get("content-length")
  const contentByteLength = contentLength ? Number(contentLength) : null
  if (
    maxBytes != null &&
    contentByteLength != null &&
    Number.isFinite(contentByteLength) &&
    contentByteLength > maxBytes
  ) {
    throw tooLarge("bytes")
  }

  const body = response.body
  if (!body) {
    const buffer = await response.arrayBuffer()
    if (maxBytes != null && buffer.byteLength > maxBytes) {
      throw tooLarge("bytes")
    }
    return readBoundedInlineText(new TextDecoder().decode(buffer), bounds)
  }

  const reader = body.getReader()
  const decoder = new TextDecoder()
  let receivedBytes = 0
  let text = ""

  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    receivedBytes += value.byteLength
    if (maxBytes != null && receivedBytes > maxBytes) {
      await reader.cancel()
      throw tooLarge("bytes")
    }
    text += decoder.decode(value, { stream: true })
  }

  text += decoder.decode()
  return readBoundedInlineText(text, bounds)
}

async function readBoundedBlobText(
  blob: Blob,
  bounds: { maxBytes?: number; maxLines?: number }
) {
  if (bounds.maxBytes != null && blob.size > bounds.maxBytes) {
    throw tooLarge("bytes")
  }
  return readBoundedInlineText(await blob.text(), bounds)
}

function readBoundedInlineText(
  text: string,
  { maxBytes, maxLines }: { maxBytes?: number; maxLines?: number }
) {
  if (
    maxBytes != null &&
    new TextEncoder().encode(text).byteLength > maxBytes
  ) {
    throw tooLarge("bytes")
  }
  if (maxLines != null && text.split("\n").length > maxLines) {
    throw tooLarge("lines")
  }
  return text
}

function tooLarge(reason: "bytes" | "lines") {
  return new ResourceError({
    kind: "too_large",
    tooLargeReason: reason,
    message: `Resource exceeds ${reason} limit.`,
  })
}

function parseContentRange(value: string | null) {
  if (!value) return undefined
  const match = value.match(/bytes\s+(\d+)-(\d+)\/(\d+|\*)/i)
  if (!match) return undefined
  return {
    start: Number(match[1]),
    end: Number(match[2]),
    total: match[3] === "*" ? null : Number(match[3]),
  }
}

function isAbortError(error: unknown) {
  return error instanceof DOMException && error.name === "AbortError"
}

"use client"

import * as React from "react"

import { type DownloadCapability } from "@/lib/viewer-resource"

export function useDownloadHref(download: DownloadCapability): string | null {
  const [objectUrl, setObjectUrl] = React.useState<string | null>(null)
  const downloadKind = download.kind
  const href = download.kind === "href" ? download.href : null
  const blob = download.kind === "blob" ? download.blob : null
  const text = download.kind === "text" ? download.text : null
  const mimeType = download.kind === "text" ? download.mimeType : null

  React.useEffect(() => {
    if (downloadKind === "href" || downloadKind === "none") {
      setObjectUrl(null)
      return
    }

    const url = URL.createObjectURL(
      blob ??
        new Blob([text ?? ""], {
          type: mimeType ?? "text/plain;charset=utf-8",
        })
    )
    setObjectUrl(url)
    return () => URL.revokeObjectURL(url)
  }, [blob, downloadKind, mimeType, text])

  return href ?? objectUrl
}

export function ViewerDownloadAnchor({
  download,
  label = "Download",
}: {
  download: DownloadCapability
  label?: string
}) {
  const href = useDownloadHref(download)
  if (!href) return <a aria-label={label} aria-disabled="true" />
  return (
    <a
      href={href}
      download={download.fileName}
      aria-label={label}
      title={label}
    />
  )
}

export interface PptxSize {
  width: number
  height: number
}

export interface PptxSlideOverlayProps {
  /** 1-based slide index. */
  slideNumber: number
  /** Rendered slide size in CSS pixels, after scale and rotation. */
  width: number
  height: number
  scale: number
  rotation: number
}

export interface PptxResetInput {
  identityKey?: string
  src?: string
  scale?: number
  defaultScale?: number
  eager?: boolean
}

export interface PptxBitmapCacheInput {
  slideIndex: number
  renderScale: number
}

export const DEFAULT_PPTX_SLIDE_SIZE = {
  width: 960,
  height: 720,
} satisfies PptxSize

export function getPptxFitScale(
  containerWidth: number | null,
  baseWidth: number
) {
  if (!containerWidth || !Number.isFinite(containerWidth) || baseWidth <= 0) {
    return 1
  }
  return clamp((containerWidth - 32) / baseWidth, 0.1, 5)
}

export function getPptxResetKey({
  identityKey,
  src,
  scale,
  defaultScale,
  eager,
}: PptxResetInput) {
  return [
    identityKey ?? src ?? "",
    scale ?? defaultScale ?? "fit",
    eager ? "eager" : "settled",
  ].join("\u0000")
}

export function getPptxBitmapCacheKey({
  slideIndex,
  renderScale,
}: PptxBitmapCacheInput) {
  return `${slideIndex}@${Math.round(renderScale * 1000)}`
}

export function getScaledSlideSize(
  baseSize: PptxSize,
  zoomScale: number
): PptxSize {
  return {
    width: baseSize.width * zoomScale,
    height: baseSize.height * zoomScale,
  }
}

export function getVisibleSlideSize(
  slideSize: PptxSize,
  rotation: number
): PptxSize {
  return getRotatedSize(slideSize, rotation)
}

export function getRotatedSize(size: PptxSize, rotation: number): PptxSize {
  const normalized = ((rotation % 360) + 360) % 360
  if (normalized === 90 || normalized === 270) {
    return { width: size.height, height: size.width }
  }
  return size
}

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

import { DEFAULT_PPTX_SLIDE_SIZE, type PptxSize } from "./pptx-viewer-core"

// EMU (English Metric Units) -> CSS px at 96dpi. OOXML measures in EMU;
// 914400 EMU = 1 inch, 96 px = 1 inch, so 9525 EMU = 1 px.
const EMU_PER_PX = 9525

export type PptxXmlParser = (xml: string) => Document | null

export function defaultPptxXmlParser(xml: string): Document | null {
  if (typeof DOMParser === "undefined") return null
  return new DOMParser().parseFromString(xml, "application/xml")
}

export function parsePptxSlideSize(
  xml: string | null | undefined,
  parseXml: PptxXmlParser = defaultPptxXmlParser
): PptxSize {
  if (!xml) {
    return DEFAULT_PPTX_SLIDE_SIZE
  }

  const document = parseXml(xml)
  if (!document) return DEFAULT_PPTX_SLIDE_SIZE

  const parseError = document.getElementsByTagName("parsererror")[0]
  if (parseError) return DEFAULT_PPTX_SLIDE_SIZE

  const slideSize = [...document.getElementsByTagName("*")].find(
    (element) => element.localName === "sldSz"
  )
  if (!slideSize) return DEFAULT_PPTX_SLIDE_SIZE

  const widthEmu = Number(slideSize.getAttribute("cx"))
  const heightEmu = Number(slideSize.getAttribute("cy"))
  if (
    !Number.isFinite(widthEmu) ||
    !Number.isFinite(heightEmu) ||
    widthEmu <= 0 ||
    heightEmu <= 0
  ) {
    return DEFAULT_PPTX_SLIDE_SIZE
  }

  return {
    width: Math.round(widthEmu / EMU_PER_PX),
    height: Math.round(heightEmu / EMU_PER_PX),
  }
}

export interface Disposable {
  dispose(): void
}

export class DisposableLruCache<K, V extends Disposable> {
  private values = new Map<K, V>()

  constructor(private readonly limit: number) {}

  get size() {
    return this.values.size
  }

  get(key: K): V | undefined {
    const value = this.values.get(key)
    if (value !== undefined) {
      this.values.delete(key)
      this.values.set(key, value)
    }
    return value
  }

  set(key: K, value: V) {
    const existing = this.values.get(key)
    if (existing) existing.dispose()
    this.values.delete(key)
    this.values.set(key, value)
    this.evict()
  }

  delete(key: K) {
    const value = this.values.get(key)
    if (!value) return
    this.values.delete(key)
    value.dispose()
  }

  clear() {
    for (const value of this.values.values()) value.dispose()
    this.values.clear()
  }

  private evict() {
    while (this.values.size > this.limit) {
      const oldest = this.values.keys().next().value as K | undefined
      if (oldest === undefined) break
      this.delete(oldest)
    }
  }
}

export class PptxBitmapEntry implements Disposable {
  constructor(readonly bitmap: ImageBitmap) {}

  dispose() {
    this.bitmap.close()
  }
}

"use client"

import * as React from "react"

import { type ViewerResource } from "@/lib/viewer-resource"

import { getPptxSource, type PptxSource } from "./pptx-viewer-source"

/** Retains the cached source for the mounted lifetime of the viewer. */
export function useRetainedPptxSource(resource: ViewerResource): PptxSource {
  const sourcePromise = React.useMemo(() => getPptxSource(resource), [resource])
  const source = React.use(sourcePromise)
  React.useEffect(() => source.retain(), [source])
  return source
}

import type * as PptxNS from "pptxviewjs"

import { ResourceError, type ViewerResource } from "@/lib/viewer-resource"

import { DEFAULT_PPTX_SLIDE_SIZE, type PptxSize } from "./pptx-viewer-core"
import { parsePptxSlideSize } from "./pptx-viewer-presentation"

type PptxModule = typeof PptxNS

interface JSZipLike {
  loadAsync(data: ArrayBuffer): Promise<{
    file(path: string): { async(type: "string"): Promise<string> } | null
  }>
}

export type PptxRendererErrorKind =
  | "fetch_failed"
  | "load_failed"
  | "render_failed"
  | "disposed"

export class PptxRendererError extends Error {
  constructor(
    readonly kind: PptxRendererErrorKind,
    message: string,
    readonly cause?: unknown
  ) {
    super(message)
    this.name = "PptxRendererError"
  }
}

export interface PptxRenderInput {
  slideIndex: number
  canvas: HTMLCanvasElement
  renderScale: number
}

export interface PptxRenderer {
  slideCount: number
  baseSize: PptxSize
  renderSlide(input: PptxRenderInput): Promise<void>
  dispose(): void
}

let pptxModulePromise: Promise<PptxModule> | null = null
let jszipPromise: Promise<JSZipLike> | null = null

function loadPptx(): Promise<PptxModule> {
  if (!pptxModulePromise) pptxModulePromise = import("pptxviewjs")
  return pptxModulePromise
}

function loadJSZip(): Promise<JSZipLike> {
  if (!jszipPromise) {
    jszipPromise = import("jszip").then(
      (mod) =>
        ((mod as { default?: unknown }).default ?? mod) as unknown as JSZipLike
    )
  }
  return jszipPromise
}

async function readSlideSize(buffer: ArrayBuffer): Promise<PptxSize> {
  try {
    const JSZip = await loadJSZip()
    const zip = await JSZip.loadAsync(buffer)
    const xml = await zip.file("ppt/presentation.xml")?.async("string")
    return parsePptxSlideSize(xml)
  } catch {
    return DEFAULT_PPTX_SLIDE_SIZE
  }
}

async function readPptxResource(resource: ViewerResource) {
  try {
    return await resource.readArrayBuffer()
  } catch (error) {
    if (error instanceof ResourceError && error.kind === "http_error") {
      throw new PptxRendererError(
        "fetch_failed",
        `Failed to load presentation: ${error.status}`,
        error
      )
    }
    throw new PptxRendererError(
      "fetch_failed",
      "Failed to fetch presentation.",
      error
    )
  }
}

export async function createPptxRenderer(
  resource: ViewerResource
): Promise<PptxRenderer> {
  const buffer = await readPptxResource(resource)
  const [pptx, baseSize] = await Promise.all([
    loadPptx(),
    readSlideSize(buffer),
  ])
  const { PPTXViewer } = pptx
  const offscreen = document.createElement("canvas")
  const viewer = new PPTXViewer({
    canvas: offscreen,
    slideSizeMode: "actual",
    autoChartRerenderDelayMs: 0,
  })

  try {
    await viewer.loadFile(buffer)
  } catch (error) {
    throw new PptxRendererError(
      "load_failed",
      "Failed to parse presentation.",
      error
    )
  }

  let disposed = false

  return {
    slideCount: viewer.getSlideCount(),
    baseSize,
    async renderSlide({ slideIndex, canvas, renderScale }) {
      if (disposed) {
        throw new PptxRendererError(
          "disposed",
          "Presentation renderer was disposed."
        )
      }
      try {
        await viewer.renderSlide(slideIndex, canvas, {
          scale: renderScale,
          quality: "high",
        })
      } catch (error) {
        throw new PptxRendererError(
          "render_failed",
          `Failed to render slide ${slideIndex + 1}.`,
          error
        )
      }
    },
    dispose() {
      if (disposed) return
      disposed = true
      viewer.destroy?.()
    },
  }
}

export function resetPptxRendererModules() {
  pptxModulePromise = null
  jszipPromise = null
}

export const PPTX_SCROLL_IDLE_MS = 120

export interface PptxScrollActivity {
  handleScroll(): void
  isScrolling(): boolean
  onIdle(callback: () => void): () => void
}

export function createPptxScrollActivity(
  idleMs = PPTX_SCROLL_IDLE_MS
): PptxScrollActivity {
  let isScrolling = false
  let timer = 0
  const waiters = new Set<() => void>()

  return {
    handleScroll() {
      isScrolling = true
      clearTimeout(timer)
      timer = window.setTimeout(() => {
        isScrolling = false
        const pending = [...waiters]
        waiters.clear()
        for (const callback of pending) callback()
      }, idleMs)
    },
    isScrolling: () => isScrolling,
    onIdle(callback: () => void) {
      waiters.add(callback)
      return () => waiters.delete(callback)
    },
  }
}

